import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Interface: RaycastOptions","description":"","frontmatter":{},"headers":[],"relativePath":"api/spool/interfaces/RaycastOptions.md","filePath":"api/spool/interfaces/RaycastOptions.md"}'),c={name:"api/spool/interfaces/RaycastOptions.md"};function s(n,e,i,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">spool</a> / RaycastOptions</p><h1 id="interface-raycastoptions" tabindex="-1">Interface: RaycastOptions <a class="header-anchor" href="#interface-raycastoptions" aria-label="Permalink to &quot;Interface: RaycastOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L14" target="_blank" rel="noreferrer">plugins/raycast/index.ts:14</a></p><p>Options for a block raycast that marches <code>^</code> through air and runs <code>onHit</code> at the first block.</p><p>No entities or macros. You decide what a hit does; <code>hitOn</code> filters which blocks count.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="hiton" tabindex="-1">hitOn? <a class="header-anchor" href="#hiton" aria-label="Permalink to &quot;hitOn?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>hitOn?</strong>: <code>BlockValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L25" target="_blank" rel="noreferrer">plugins/raycast/index.ts:25</a></p><p>Blocks that count as a hit (id or <code>Block.tag(...)</code>). Default: any non-air block. The ray still stops at the first non-air block; a non-match is a miss.</p><hr><h3 id="maxsteps" tabindex="-1">maxSteps <a class="header-anchor" href="#maxsteps" aria-label="Permalink to &quot;maxSteps&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>maxSteps</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L18" target="_blank" rel="noreferrer">plugins/raycast/index.ts:18</a></p><p>Maximum reach, in steps of <code>stepBlocks</code>.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L16" target="_blank" rel="noreferrer">plugins/raycast/index.ts:16</a></p><p>Function path suffix and step-slot name (<code>raycast/&lt;name&gt;</code>). Must be unique per pack.</p><hr><h3 id="stepblocks" tabindex="-1">stepBlocks? <a class="header-anchor" href="#stepblocks" aria-label="Permalink to &quot;stepBlocks?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>stepBlocks?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L20" target="_blank" rel="noreferrer">plugins/raycast/index.ts:20</a></p><p>Stride per step along the line of sight, in blocks. Default <code>0.5</code>.</p><hr><h3 id="stopat" tabindex="-1">stopAt? <a class="header-anchor" href="#stopat" aria-label="Permalink to &quot;stopAt?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>stopAt?</strong>: <code>Selector</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L33" target="_blank" rel="noreferrer">plugins/raycast/index.ts:33</a></p><p>Entities that end the ray early and run <a href="#onreach">onReach</a> instead of <a href="#onhit">onHit</a>.</p><p>Turns the ray into a line-of-sight check. Give it <code>distance</code> slack, since the ray samples every <code>stepBlocks</code> and <code>distance</code> measures to feet.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="onhit" tabindex="-1">onHit()? <a class="header-anchor" href="#onhit" aria-label="Permalink to &quot;onHit()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onHit</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L44" target="_blank" rel="noreferrer">plugins/raycast/index.ts:44</a></p><p>Runs at the hit block (only matching blocks with <code>hitOn</code>). Optional for pure line-of-sight rays.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="onreach" tabindex="-1">onReach()? <a class="header-anchor" href="#onreach" aria-label="Permalink to &quot;onReach()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onReach</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/raycast/index.ts#L39" target="_blank" rel="noreferrer">plugins/raycast/index.ts:39</a></p><p>Runs where <a href="#stopat">stopAt</a> matched. Ending it with <code>ctx.return_(1)</code> makes the whole ray return 1, so <code>execute if function &lt;ref&gt;.cast</code> is a line-of-sight test.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-1" tabindex="-1">ctx <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',51)])])}const f=t(c,[["render",s]]);export{b as __pageData,f as default};
